invalidAccess.example:
#include <stdlib.h>

int main() {
    // Exemple de lectura/escriptura invàlida
    int *arr = (int*)malloc(sizeof(int) * 5);
    arr[5] = 10;  // Accés fora de límits
    free(arr);
    return 0;
}

uninitializedValue.example:
#include <stdio.h>

int main() {
    int x;  // No inicialitzada
    if (x > 0) {  // Ús de valor no inicialitzat
        printf("Positiu\n");
    }
    return 0;
}

doubleFree.example:
#include <stdlib.h>

int main() {
    int *ptr = (int*)malloc(sizeof(int));
    free(ptr);
    free(ptr);  // Doble alliberament
    return 0;
}

mismatchedFree.example:
#include <stdlib.h>

int main() {
    int *arr = (int*)malloc(10 * sizeof(int));
    delete[] arr;  // Funció d'alliberament incorrecta
    return 0;
}

overlappingMemory.example:
#include <string.h>

int main() {
    char str[20] = "Hola, Món!";
    memcpy(str + 5, str, 10);  // Superposició de memòria
    return 0;
}
